WITH remaining_keys AS (SELECT customer_id, channel FROM orders EXCEPT ALL SELECT customer_id, channel FROM orders WHERE customer_id IN (1, 6, 23)), verified AS (SELECT s.* FROM orders s INNER JOIN remaining_keys k ON s.customer_id = k.customer_id AND s.channel = k.channel) SELECT DATE_TRUNC('QUARTER', order_date) AS quarter_start, SIZE(COLLECT_SET(channel)) AS num_channels, COUNT_IF(status = 'COMPLETED') AS completed_events, PERCENTILE_APPROX(discount, ARRAY(0.25, 0.5, 0.75)) AS discount_quartiles, CORR(amount, discount) AS corr_amount_discount, GROUPING_ID() AS gid FROM verified GROUP BY ROLLUP (DATE_TRUNC('QUARTER', order_date)) ORDER BY corr_amount_discount
